-- Seed evidence-based practical assessments across the current training library.

update public.training_assessments
set rubric = '[{"id":"evidence","label":"Evidence accuracy","weight":20,"description":"Uses the supplied fictional records accurately, distinguishes verified facts from assumptions, and does not invent missing information."},{"id":"prioritization","label":"Prioritization and judgment","weight":15,"description":"Orders work by urgency, dependency, customer or business impact, and the authority available to the VA."},{"id":"execution","label":"Workflow execution","weight":20,"description":"Produces usable work outputs, follows the requested workflow, and handles exceptions instead of only describing general best practice."},{"id":"boundaries","label":"Professional boundaries and safety","weight":20,"description":"Protects privacy, security, financial or regulatory boundaries and escalates decisions that require authorized or specialist judgment.","hard_fail":true},{"id":"qa","label":"QA and documentation","weight":15,"description":"Checks source data, records changes and exceptions, preserves auditability, and defines how work should be verified before closure."},{"id":"handoff","label":"Communication and handoff","weight":10,"description":"Writes clear client, customer, team, or reviewer communications with owners, next actions, deadlines, and unresolved risks."}]'::jsonb, updated_at = now()
where assessment_type = 'practical';

update public.training_assessments a
set resource_pack = '[{"id":"inbox","title":"Morning inbox and task queue","kind":"brief","content":"08:05 password-reset alert not requested by client\n08:12 customer asks to move tomorrow 10:00 appointment\n08:20 supplier says invoice INV-418 is overdue\n08:25 client writes: ''Supplier call 10 AM Thursday''\nCRM cleanup: 60 rows due 17:00\nResearch: find 3 replacement suppliers with source links"},{"id":"crm","title":"CRM cleanup sample","kind":"csv","content":"company,contact,status,owner\nAcme Co,Jane Cruz,Followup,\nACME CO.,Jane Cruz,follow up,Erin\nNorthstar Ltd,Mark Lee,FU,Paolo\nBrightWorks,,New,\nNorth Star Ltd,Mark Lee,Contacted,Paolo"},{"id":"rules","title":"Client working rules","kind":"policy","content":"Never reset passwords from an unsolicited email. Confirm time zone when a meeting request is ambiguous. Supplier payments require owner approval. Bulk spreadsheet cleanup must be recoverable. Research must include source links and checked date."}]'::jsonb, updated_at = now()
from public.training_courses c
where a.course_id = c.id and c.slug = 'virtual-assistant-foundations';

update public.training_assessments a
