set resource_pack = '[{"id":"file","title":"Broker file checklist","kind":"csv","content":"item,status\nID documents,Complete\nPayslips,Missing latest\nBank statements,Complete\nLiving expenses,Inconsistent values\nExisting liabilities,One statement missing\nProperty contract,Complete"},{"id":"research","title":"Lender research extract","kind":"csv","content":"lender,rate,policy_note,checked_date\nLender A,5.89%,Policy A requires 2 payslips,2026-09-23\nLender B,5.79%,Policy B has tighter expense verification,2026-09-23\nLender C,6.05%,Faster stated turnaround,2026-09-23"},{"id":"scope","title":"Mortgage administration boundary","kind":"policy","content":"VA may gather documents, enter fact-find data, record lender facts, package applications and track conditions. Product recommendation, best-interests assessment, borrowing-capacity judgment, credit assistance and financial advice belong to the licensed/authorized broker."}]'::jsonb, updated_at = now()
from public.training_courses c
